pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(bytes32 assertionId, address disputeCaller) public {
        // Call isDisputeAllowed directly and capture the return value
        bool result = c.isDisputeAllowed(assertionId, disputeCaller);
        // General rule: isDisputeAllowed always returns true
        assertTrue(result);
    }
}

